// Bridge between ggml's Metal backend and ccv's Conv3DKernel (liuliu/ccv,
// BSD-3, see COPYING in this directory).
//
// The kernel source is generated by Conv3DKernel::createSource(); everything
// below only builds the pipeline for a given descriptor and dispatches it, in
// the same way as the non-NA path of ccv_nnc_mfa_conv3d.cpp:
//
//   tensors[0] activation  NDHWC F32, [OD+KD-1][OH+KH-1-2*pad_top][OW+KW-1-2*pad_left][IC]
//   tensors[1] weights     [OC][KD][KH][KW][IC] F32
//   tensors[2] output      NDHWC F32, [OD][OH][OW][OC]
//
// Adapter code derived from ccv's ccv_nnc_mfa_conv3d.cpp (non-NA path), not part
// of upstream ccv: licensed BSD-3 like the sources it wraps, see COPYING.
#include "ggml-metal-conv3d-ccv.h"

#include <algorithm>
#include <cstdio>
#include <mutex>
#include <vector>

#include "Conv3DDescriptor.hpp"
#include "Conv3DKernel.hpp"
#include "Conv3DKernelDescriptor.hpp"
#include "ccv_nnc_mfa_error.hpp"

#define LOG_WARN(...) do { fprintf(stderr, "[conv3d-ccv] " __VA_ARGS__); fprintf(stderr, "\n"); } while (0)

struct ggml_metal_conv3d_ccv {
    // cache key
    void * device;

    ggml_metal_conv3d_ccv_params params;

    Conv3DDescriptor desc;

    Conv3DKernel * kernel;

    NS::SharedPtr<MTL::ComputePipelineState> pipeline;

    MTL::Size grid;
    uint32_t   threadgroup_size;
};

static std::mutex g_mutex;
static std::vector<ggml_metal_conv3d_ccv *> g_cache;

static bool ggml_metal_conv3d_ccv_same(const ggml_metal_conv3d_ccv * k, void * device,
                                       const ggml_metal_conv3d_ccv_params * p) {
    return k->device == device &&
        k->params.IC == p->IC && k->params.OC == p->OC &&
        k->params.KD == p->KD && k->params.KH == p->KH && k->params.KW == p->KW &&
        k->params.OD == p->OD && k->params.OH == p->OH && k->params.OW == p->OW &&
        k->params.pad_left == p->pad_left && k->params.pad_right == p->pad_right &&
        k->params.pad_top == p->pad_top && k->params.pad_bottom == p->pad_bottom;
}

static MTL::ComputePipelineState * ggml_metal_conv3d_ccv_compile(Conv3DKernel * kernel,
                                                                 MTL::Device * device,
                                                                 const uint32_t od,
                                                                 const uint32_t oh,
                                                                 const uint32_t ow) {
    NS::Error * error = nil;

    auto constants = NS::TransferPtr(MTL::FunctionConstantValues::alloc()->init());
    uint32_t depth  = od;
    uint32_t height = oh;
    uint32_t width  = ow;
    constants->setConstantValue(&depth,  MTL::DataTypeUInt, NS::UInteger(0));
    constants->setConstantValue(&height, MTL::DataTypeUInt, NS::UInteger(1));
    constants->setConstantValue(&width,  MTL::DataTypeUInt, NS::UInteger(2));

    MTL::Function * function = kernel->library->newFunction(
            NS::String::string("conv3d", NS::UTF8StringEncoding), constants.get(), &error);
    if (!function) {
        if (error) {
            LOG_WARN("failed to create function: %s",
                    error->localizedDescription()->cString(NS::UTF8StringEncoding));
        }
        return nullptr;
    }

    auto pipeline_desc = NS::TransferPtr(MTL::ComputePipelineDescriptor::alloc()->init());
    pipeline_desc->setComputeFunction(function);

    error = nil;
    MTL::ComputePipelineState * pipeline = device->newComputePipelineState(
            pipeline_desc.get(), MTL::PipelineOptionNone, nullptr, &error);
    function->release();

    if (!pipeline) {
        if (error) {
            LOG_WARN("failed to create pipeline state: %s",
                    error->localizedDescription()->cString(NS::UTF8StringEncoding));
        }
        return nullptr;
    }

    return pipeline;
}

static ggml_metal_conv3d_ccv * ggml_metal_conv3d_ccv_build(void * device_ptr,
                                                           const ggml_metal_conv3d_ccv_params * p) {
    MTL::Device * device = (MTL::Device *) device_ptr;

    // block size from ccv_nnc_mfa_conv3d.cpp (non-NA path)
    const uint32_t rounded_output_channels = ((uint32_t) p->OC + 31u) / 32u * 32u;
    const uint32_t block_n = std::min<uint32_t>(std::max<uint32_t>(rounded_output_channels, 32u), 64u);

    ggml_metal_conv3d_ccv * res = new ggml_metal_conv3d_ccv();

    res->device = device_ptr;
    res->params = *p;

    res->desc.dataType           = 3; // float32
    res->desc.batchDimension     = 1;
    res->desc.inputChannels      = p->IC;
    res->desc.outputChannels     = p->OC;
    res->desc.blockDimensions    = simd::ushort2{(unsigned short) block_n, 32};
    res->desc.paddingLeft        = p->pad_left;
    res->desc.paddingRight       = p->pad_right;
    res->desc.paddingTop         = p->pad_top;
    res->desc.paddingBottom      = p->pad_bottom;
    res->desc.matrixDimensions   = simd::uint3{(uint32_t) p->OD, (uint32_t) p->OH, (uint32_t) p->OW};
    res->desc.kernelDimensions   = simd::uint3{(uint32_t) p->KD, (uint32_t) p->KH, (uint32_t) p->KW};
    res->desc.useBias            = false;

    Conv3DKernelDescriptor kernel_desc(
            res->desc.blockDimensions,
            simd::ushort3{(unsigned short) p->KD, (unsigned short) p->KH, (unsigned short) p->KW},
            3, p->IC, p->OC,
            p->pad_left, p->pad_right, p->pad_top, p->pad_bottom,
            false);

    res->kernel = new Conv3DKernel(kernel_desc, device);
    if (!res->kernel->library.get()) {
        delete res->kernel;
        delete res;
        return nullptr;
    }

    MTL::ComputePipelineState * pipeline = ggml_metal_conv3d_ccv_compile(
            res->kernel, device, p->OD, p->OH, p->OW);
    if (!pipeline) {
        delete res->kernel;
        delete res;
        return nullptr;
    }
    res->pipeline = NS::TransferPtr(pipeline);

    res->threadgroup_size = res->kernel->threadgroupSize(res->pipeline.get(), res->desc);
    res->grid = res->kernel->threadgroupsPerGrid(res->desc);

    LOG_WARN("compiled conv3d %dx%dx%d, %d -> %d, pad %d/%d, %u threads",
            p->OD, p->OH, p->OW, p->IC, p->OC, p->pad_top, p->pad_left, res->threadgroup_size);

    return res;
}

ggml_metal_conv3d_ccv * ggml_metal_conv3d_ccv_get(void * device,
                                                  const ggml_metal_conv3d_ccv_params * params) {
    std::lock_guard<std::mutex> lock(g_mutex);

    for (ggml_metal_conv3d_ccv * k : g_cache) {
        if (ggml_metal_conv3d_ccv_same(k, device, params)) {
            return k;
        }
    }

    ggml_metal_conv3d_ccv * k = ggml_metal_conv3d_ccv_build(device, params);
    if (k) {
        g_cache.push_back(k);
    }

    return k;
}

void ggml_metal_conv3d_ccv_encode(ggml_metal_conv3d_ccv * kernel,
                                  void * encoder,
                                  void * src, size_t src_offs,
                                  void * w,   size_t w_offs,
                                  void * dst, size_t dst_offs) {
    MTL::ComputeCommandEncoder * enc = (MTL::ComputeCommandEncoder *) encoder;

    enc->setComputePipelineState(kernel->pipeline.get());
    enc->setBuffer((MTL::Buffer *) src, src_offs, 0);
    enc->setBuffer((MTL::Buffer *) w,   w_offs,   1);
    enc->setBuffer((MTL::Buffer *) dst, dst_offs, 2);

    const MTL::Size threads(kernel->threadgroup_size, 1, 1);
    enc->dispatchThreadgroups(kernel->grid, threads);
}
